package net.minecraft.item;
public class ItemStack {public static final ItemStack EMPTY=new ItemStack(null,0,0,false); public final Object item; public int count,damage;public final boolean tool; public String tag="";public ItemStack(Object i,int c,int d,boolean t){item=i;count=c;damage=d;tool=t;}public boolean isEmpty(){return item==null||count<=0;}public ItemStack copy(){ItemStack s=new ItemStack(item,count,damage,tool);s.tag=tag;return s;}public Object getItem(){return item;}public int getMetadata(){return damage;}public int getItemDamage(){return damage;}public int getMaxDamage(){return 100;}public boolean isItemStackDamageable(){return tool;}public static boolean areItemStackTagsEqual(ItemStack a,ItemStack b){return a.tag.equals(b.tag);}}